555	+import { rulesPresets, type RulesPresetId, type SeaMapDefinition } from "@pirate-sea-race/content";
556	+import type { FruitInspectedMessage, TestFruits } from "@pirate-sea-race/protocol";
557	+import { createFruitState, inspectPedestal, type FruitSite, type FruitState } from "@pirate-sea-race/simulation/fruits";
558	+import { dockCentre, islandDocks, MATCH_PRESET } from "./objectives.js";
559	+
560	+/**
561	+ * The room's side of §9's fruit pedestals (`docs/fruits.md`): where the pedestals stand on the sea, a match's deal and
562	+ * what an inspection sends. The fruit rules alone decide who eats what; nothing here eats a fruit.
563	+ */
564	+
565	+/** A pedestal on the sea: the fruit rules' site, plus the island and the dock a player moors at to reach it. */
566	+export interface PedestalSite extends FruitSite {
567	+  readonly island: number;
568	+  readonly dock: number;
569	+}
570	+
571	+/**
572	+ * The pedestal sites (§9: distinct from the rubbing sources): one on each regular island, at that island's highest-id
573	+ * dock, so it stands at another dock than the island's first source whenever the island has more than one. Pedestal
574	+ * `pedestal-<island>`, in island order.
575	+ */
576	+export function pedestalSites(map: SeaMapDefinition, presetId: RulesPresetId = MATCH_PRESET): PedestalSite[] {
577	+  const sites: PedestalSite[] = [];
578	+  for (let island = 0; island < rulesPresets[presetId].islands; island++) {
579	+    const docks = islandDocks(map, island);
580	+    if (docks.length === 0) throw new Error(`${map.name}: island ${island} has no dock for its pedestal`);
581	+    const dock = Math.max(...docks);
582	+    sites.push({ id: `pedestal-${island}`, island, dock, ...dockCentre(map, dock) });
583	+  }
584	+  return sites;
585	+}
586	+
587	+export interface MatchFruitsOptions {
588	+  readonly sites: readonly PedestalSite[];
589	+  /** The fruit seed derived from the match's master secret (`deriveSeed('fruit')`), never the match code (§3, §16). */
590	+  readonly seed: number;
591	+  /** Test-only: the kit on each site, in site order, instead of the seeded deal. */
592	+  readonly layout?: TestFruits | undefined;
593	+}
594	+
595	+/**
596	+ * A new match's fruit state: the fruit rules' seeded deal onto the sites. A test-only layout replaces the deal's kits,
597	+ * and must hold the same fruit as the deal (two of each kit).
598	+ */
599	+export function createMatchFruits(options: MatchFruitsOptions): FruitState {
600	+  const dealt = createFruitState(options.sites, options.seed >>> 0, rulesPresets[MATCH_PRESET]);
601	+  const layout = options.layout;
602	+  if (layout === undefined) return dealt;
603	+  const deck = dealt.pedestals.map((pedestal) => pedestal.kit).sort();
604	+  if ([...layout].sort().join() !== deck.join()) throw new Error(`test fruit deal: ${layout.join(",")} is not a deal of ${deck.join(",")}`);
605	+  return { ...dealt, pedestals: dealt.pedestals.map((pedestal, index) => ({ ...pedestal, kit: layout[index]! })) };
606	+}
607	+
608	+/** The pedestal at a dock, if one stands there. */
609	+export function pedestalAtDock(sites: readonly PedestalSite[], dock: number): PedestalSite | undefined {
610	+  return sites.find((site) => site.dock === dock);
611	+}
612	+
613	+/**
614	+ * What an inspection of a pedestal sends its inspector (§9, §16): the fruit's kit with its description, or that the
615	+ * pedestal is empty. Only ever sent to a player moored at that pedestal's dock.
616	+ */
617	+export function inspectionOf(fruits: FruitState, site: PedestalSite): FruitInspectedMessage {
618	+  // Every site is one of the state's pedestals.
619	+  const inspected = inspectPedestal(fruits, site.id)!;
620	+  if (!inspected.full) return { island: site.island, full: false };
621	+  const { name, specials, advantage, vulnerability } = inspected.description;
622	+  return { island: site.island, full: true, kit: inspected.kit, name, specials: [specials[0], specials[1]], advantage, vulnerability };
623	+}
