855	@@ -0,0 +1,152 @@
856	+import { fighterTells, findMove, zoneBox, type DuelConfig, type DuelState, type FighterState, type PlayerIndex, type WorldBox } from "@pirate-sea-race/simulation/duel";
857	+
858	+/**
859	+ * What the arena draws of a duel's state (§9's "what the renderer must show", `docs/fruit-kits.md`), as plain shapes in
860	+ * arena pixels, from the duel's own `fighterTells`: each fighter's body (its stance's hurtbox), its bolt as a moving
861	+ * sprite, its smoke screen as a translucent zone, a generic startup flash for a fighter the screen obscures (whose move
862	+ * name is then hidden), the feint's reappearance, and the threat hitbox of a move that strikes. A cast, a feint or a
863	+ * screen never draws its box as a threat. No Phaser here: the arena scene copies this onto its canvas, and unit tests
864	+ * read it directly.
865	+ */
866	+
867	+/** The arena's height on the canvas, and the floor's height in pixels from its top. */
868	+export const ARENA_HEIGHT = 320;
869	+export const FLOOR = ARENA_HEIGHT - 40;
870	+
871	+export interface Rect {
872	+  readonly x: number;
873	+  readonly y: number;
874	+  readonly w: number;
875	+  readonly h: number;
876	+}
877	+
878	+/** A box in sub-pixels (y up from the floor) as arena pixels (y down from the top). */
879	+export function toCanvas(config: DuelConfig, box: WorldBox): Rect {
880	+  const sub = config.moveset.arena.subPixelsPerPixel;
881	+  return { x: box.x0 / sub, y: FLOOR - box.y1 / sub, w: (box.x1 - box.x0) / sub, h: (box.y1 - box.y0) / sub };
882	+}
883	+
884	+export interface FighterDrawing {
885	+  readonly index: PlayerIndex;
886	+  readonly body: Rect;
887	+  readonly facing: number;
888	+  /** Inside a smoke screen: the move being started is hidden, and a generic flash shows instead. */
889	+  readonly obscured: boolean;
890	+  /** A generic startup flash: an obscured fighter starting a move. */
891	+  readonly startupFlash: boolean;
892	+  /** Starting a move where the move itself may show (not obscured). */
893	+  readonly startingUp: boolean;
894	+  /** In a feint's readable reappearance. */
895	+  readonly reappearing: boolean;
896	+  /** The active hitbox of a move that strikes, drawn as a threat; null otherwise. */
897	+  readonly threat: Rect | null;
898	+  /** The text over the fighter: its action and move, with the move hidden while an obscured startup runs. */
899	+  readonly label: string;
900	+}
901	+
902	+export interface BoltDrawing {
903	+  readonly owner: PlayerIndex;
904	+  readonly box: Rect;
905	+}
906	+
907	+export interface ZoneDrawing {
908	+  readonly owner: PlayerIndex;
909	+  readonly box: Rect;
910	+}
911	+
912	+export interface ArenaDrawing {
913	+  readonly fighters: readonly [FighterDrawing, FighterDrawing];
914	+  readonly bolts: readonly BoltDrawing[];
915	+  readonly zones: readonly ZoneDrawing[];
916	+}
917	+
918	+/** The fighter's action with its move and the move's frame ("Flame bolt 12"), or a crouching state marked low. */
919	+function actionLabel(config: DuelConfig, fighter: FighterState): string {
920	+  if (fighter.action === "attack" && fighter.moveId !== null) return `${findMove(config.moveset, fighter.moveId).timing.name} ${fighter.actionFrame}`;
921	+  return fighter.crouching && fighter.action !== "crouch" ? `${fighter.action} (low)` : fighter.action;
922	+}
923	+
924	+/** One fighter's drawing, from its tells. */
925	+export function fighterDrawing(config: DuelConfig, fighter: FighterState, index: PlayerIndex): FighterDrawing {
926	+  const tells = fighterTells(config, fighter);
927	+  const hidden = tells.obscured && tells.startingUp;
928	+  return {
929	+    index,
930	+    body: toCanvas(config, tells.hurtbox),
931	+    facing: tells.facing,
932	+    obscured: tells.obscured,
933	+    startupFlash: hidden,
934	+    startingUp: tells.startingUp && !hidden,
935	+    reappearing: tells.reappearing,
936	+    threat: tells.activeHitbox === null ? null : toCanvas(config, tells.activeHitbox),
937	+    label: hidden ? "…" : actionLabel(config, fighter),
938	+  };
939	+}
940	+
941	+/** Everything the arena draws of a state: both fighters, every bolt and every smoke screen. */
942	+export function arenaDrawing(config: DuelConfig, state: DuelState): ArenaDrawing {
943	+  const [a, b] = state.fighters;
944	+  const bolts: BoltDrawing[] = [];
945	+  const zones: ZoneDrawing[] = [];
946	+  state.fighters.forEach((fighter, owner) => {
947	+    const tells = fighterTells(config, fighter);
948	+    if (tells.bolt !== null) bolts.push({ owner: owner as PlayerIndex, box: toCanvas(config, tells.bolt) });
949	+    if (fighter.zone !== null) zones.push({ owner: owner as PlayerIndex, box: toCanvas(config, zoneBox(config.moveset, fighter.zone)) });
950	+  });
951	+  return { fighters: [fighterDrawing(config, a, 0), fighterDrawing(config, b, 1)], bolts, zones };
952	+}
953	+
954	+/** What the arena scene draws §9's tells with, in arena pixels: Phaser's graphics in the scene, a recording fake in tests. */
955	+export interface ArenaPen {
956	+  /** A smoke screen: a translucent zone. */
957	+  zone(box: Rect): void;
958	+  /** A bolt: a flame sprite where it flies. */
959	+  bolt(box: Rect): void;
960	+  /** The generic startup flash around an obscured fighter's body. */
961	+  startupFlash(body: Rect): void;
962	+  /** The feint's reappearance around the fighter's body. */
963	+  reappearance(body: Rect): void;
964	+}
965	+
966	+/** Draws the tells of a drawing: every smoke screen, every bolt, and each fighter's startup flash and reappearance. */
967	+export function drawTells(pen: ArenaPen, drawing: ArenaDrawing): void {
968	+  for (const zone of drawing.zones) pen.zone(zone.box);
969	+  for (const bolt of drawing.bolts) pen.bolt(bolt.box);
970	+  for (const fighter of drawing.fighters) {
971	+    if (fighter.startupFlash) pen.startupFlash(fighter.body);
972	+    if (fighter.reappearing) pen.reappearance(fighter.body);
973	+  }
974	+}
975	+
976	+/** Outline colours: hit, blocking, staggered, thrown, a threat (a striking move's active frames), a startup, and free. */
977	+export const OUTLINE = {
978	+  hit: 0xff5a4f,
979	+  block: 0xffffff,
980	+  stagger: 0xff9f1c,
981	+  thrown: 0xc77dff,
982	+  threat: 0xff3b30,
983	+  startup: 0xfff3b0,
984	+  /** An obscured fighter's startup outline is the generic flash's white, never the move's own. */
985	+  hidden: 0xffffff,
986	+  free: 0x0b1620,
987	+} as const;
988	+
989	+/** The outline colour that tells the fighter's state at a glance; in an attack, a threat only when its move strikes. */
990	+export function outlineColor(fighter: FighterState, drawing: FighterDrawing): number {
991	+  switch (fighter.action) {
992	+    case "hitstun":
993	+    case "knockdown":
994	+      return OUTLINE.hit;
995	+    case "blockstun":
996	+      return OUTLINE.block;
997	+    case "stagger":
998	+      return OUTLINE.stagger;
999	+    case "thrown":
1000	+    case "throw-break":
1001	+      return OUTLINE.thrown;
1002	+    case "attack":
1003	+      return drawing.threat !== null ? OUTLINE.threat : drawing.startupFlash ? OUTLINE.hidden : OUTLINE.startup;
1004	+    default:
1005	+      return OUTLINE.free;
1006	+  }
1007	+}
