948	  /** The end report of a fight, as the ledger recorded its result (a quit may have decided it there first). */
949	  private endReport(duel: SeaDuel, tick: number): DuelReport {
950	    const result = findDuel(this.ledger, duel.id)?.result;
951	    if (result?.outcome === "win" && result.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: result.winner };
952	    if (result !== null && result !== undefined) return { kind: "end", duelId: duel.id, tick, outcome: result.outcome === "draw" ? "draw" : "cancelled" };
953	    const outcome = duel.machine.outcome!;
954	    if (outcome.winner !== null) return { kind: "end", duelId: duel.id, tick, outcome: "win", winner: duel.players[outcome.winner] };
955	    return { kind: "end", duelId: duel.id, tick, outcome: outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw" };
956	  }
