958	  private apply(event: EncounterEvent): void {
959	    switch (event.kind) {
960	      case "duel-reserved":
961	        this.ledgerStep("reserveDuel", reserveDuel(this.ledger, { duelId: event.duelId, players: event.players, tick: event.tick }));
962	        this.openSeaDuel(event.duelId, event.players, event.x, event.y, event.tick);
963	        return;
964	      case "duel-started":
965	        this.seaDuels.get(event.duelId)?.machine.start();
966	        return;
967	      case "duel-forfeited":
968	      case "duel-cancelled": {
969	        const duel = this.seaDuels.get(event.duelId);
970	        if (findDuel(this.ledger, event.duelId)?.phase === "fighting") {
971	          const report = event.kind === "duel-cancelled" ? { outcome: "cancelled" as const } : { outcome: "win" as const, winner: event.winner };
972	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: event.duelId, tick: event.tick, ...report }));
973	        }
974	        if (duel === undefined) return;
975	        duel.endedByRules = true;
976	        duel.ended = true;
977	        if (event.kind === "duel-cancelled") duel.machine.end(null, "cancelled");
978	        else duel.machine.end(duel.players.indexOf(event.winner) as PlayerIndex, "forfeit");
979	        return;
