990	        if (!this.simulation.ships.some((ship) => ship.id === event.playerId)) return;
991	        this.simulation = returnShip(this.config, this.simulation, event.playerId, {
992	          x: event.x,
993	          y: event.y,
994	          dock: event.kind === "player-respawned" ? (event.dockId ?? NOT_DOCKED) : NOT_DOCKED,
995	        });
