1006	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
1007	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
1008	    // A winner who attacks again while the last result is still showing: that lobby goes now.
1009	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
1010	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
1011	    const key = `d${this.nextDuelKey++}`;
1012	    const lobby = new SeaDuelSchema();
1013	    lobby.code = this.state.code;
1014	    lobby.practice = false;
1015	    this.state.duels.set(key, lobby);
1016	    const machine = new DuelMachine({
1017	      lobby,
1018	      seed: this.seedOf(`duel:${++this.duelsOpened}`),
1019	      // §9: each fighter's kit, the fruit they ate or the Duelist, fixed in the duel's frame-0 state.
1020	      kits: [kitOf(this.fruits, players[0]), kitOf(this.fruits, players[1])],
1021	      start: "called",
1022	      send: (sessionId, type, message) => this.clients.get(sessionId)?.send(type, message),
1023	    });
1024	    players.forEach((player, slot) => {
